public int findLargestSubstring(List<String> strings) {
    int largestLen = 0;
    int largestIndex = -1;
    for (int i = 0; i < strings.size(); i++) {
        String s = strings.get(i);
        for (int j = 0; j < s.length(); j++) {
            String substr = s.substring(j, j + 1);
            boolean match = true;
            for (int k = 0; k < strings.size(); k++) {
                if (k != i && !strings.get(k).contains(substr)) {
                    match = false;
                    break;
                }
            }
            if (match) {
                if (s.length() > largestLen) {
                    largestLen = s.length();
                    largestIndex = i;
                }
                break;
            }
        }
    }
    return largestIndex + 1;
}

