public double trimMean(int[] arr) {
    // Calculate the percentiles
    int minIdx = (int) (arr.length * 0.05);
    int maxIdx = (int) (arr.length * 0.95);

    // Sort the array
    Arrays.sort(arr);

    // Calculate the subarrays
    int[] subArrMin = Arrays.copyOfRange(arr, minIdx, maxIdx);
    int[] subArrMax = Arrays.copyOfRange(arr, 0, subArrMin.length);

    // Calculate the sums
    int sumMin = Arrays.stream(subArrMin).sum();
    int sumMax = Arrays.stream(subArrMax).sum();

    // Calculate the trim mean
    return (sumMin + sumMax) / (subArrMin.length + subArrMax.length);
}

