public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dp = new int[n];
    dp[0] = 0;
    for (int i = 0; i < n-1; i++) {
        for (int j = 0; j < edges.length; j++) {
            int u = edges[j][0], v = edges[j][1];
            if (!hasApple[u] && hasApple[v]) {
                dp[u] = dp[v] + 1;
            } else if (hasApple[u] && !hasApple[v]) {
                dp[v] = dp[u] + 1;
            } else if (hasApple[u]) {
                dp[v] = Math.max(dp[v], dp[u] + 1);
            } else {
                dp[v] = Math.min(dp[v], dp[u] + 1);
            }
        }
    }
    return dp[n-1];
}

