public static String sortString(String s) {
        char[] charArray = s.toCharArray();
        String sortedString = "";

        for (int i = 0; i < charArray.length; i++) {
            // find the smallest character not added to the result yet
            char smallestCharacter = findSmallestCharacter(charArray, sortedString);
            sortedString += smallestCharacter;

            // find the largest character not added to the result yet
            char largestCharacter = findLargestCharacter(charArray, sortedString);
            sortedString += largestCharacter;

            // remove the characters that were added to the result
            charArray = Arrays.stream(charArray).filter(c -> c != smallestCharacter && c != largestCharacter).toArray();
        }

        return sortedString;
    }

