public static String sortString(String s) {
        if (s == null || s.length() == 0) {
            return s;
        }

        char[] chars = s.toCharArray();
        java.util.Arrays.sort(chars);
        String result = "";

        // Step 1: Pick the smallest character from s and append it to the result.
        result += chars[0];

        // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it.
        // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it.
        for (int i = 1; i < chars.length; i++) {
            if (chars[i] < chars[i - 1]) {
                result += chars[i];
            } else if (chars[i] > chars[i - 1]) {
                result += chars[chars.length - i - 1];
            }
        }

        return result;
    }

