public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    if (sum % 2 != 0) {
        return false;
    }
    double targetAverage = (double) sum / nums.length;
    double currentAverage = 0;
    int currentLength = 0;
    for (int i = 0; i < nums.length; i++) {
        currentAverage += nums[i] / (currentLength + 1);
        currentLength++;
        if (currentAverage == targetAverage) {
            return true;
        }
    }
    return false;
}

