public boolean hasAllCodes(String s, int k) {
    // Check if k is valid
    if (k < 1 || s.length() < k) {
        return false;
    }

    // Initialize a set to store all unique substrings of length k
    Set<String> substrings = new HashSet<>();

    // Iterate through the string and add all possible substrings of length k to the set
    for (int i = 0; i <= s.length() - k; i++) {
        substrings.add(s.substring(i, i + k));
    }

    // Check if all possible substrings of length k are present in the set
    for (int i = 0; i <= Math.pow(2, k) - 1; i++) {
        String binary = Integer.toBinaryString(i);
        if (binary.length() < k) {
            binary = "0".repeat(k - binary.length()) + binary;
        }
        if (!substrings.contains(binary)) {
            return false;
        }
    }

    return true;
}

