public static String reverseWords(String s) {
    // Split the input string into words using a regex to separate by spaces
    String[] words = s.split("\\s+");

    // Initialize a new string builder to build the reversed string
    StringBuilder sb = new StringBuilder();

    // Iterate through the words and reverse each one
    for (String word : words) {
        char[] charArray = word.toCharArray();
        for (int i = charArray.length - 1; i >= 0; i--) {
            sb.append(charArray[i]);
        }
        // Add a space between each word
        sb.append(" ");
    }

    // Remove the trailing space and return the reversed string
    return sb.toString().trim();
}

